def _parse_inline(self):
    end = self._buf.find(b"\n")
    if end == -1:
        if len(self._buf) > MAX_INLINE_LEN:
            raise ProtocolError("too big inline request")
        return None
    line = bytes(self._buf[:end]).rstrip(b"\r")
    del self._buf[: end + 1]
    parts = line.split()
    return parts if parts else self.get_command()

