def command(name: str, arity: int, write: bool = False):
    def deco(fn):
        REGISTRY[name.upper()] = Command(name.upper(), fn, arity, write)
        return fn
    return deco

def check_arity(cmd, args):
    n = len(args)
    if (cmd.arity > 0 and n != cmd.arity) or (cmd.arity < 0 and n < -cmd.arity):
        raise RespError(f"ERR wrong number of arguments for '{cmd.name.lower()}' command")
